#include "lore_vcs.h"

#include <algorithm>
#include <cctype>
#include <cstdlib>
#include <format>
#include <fstream>

namespace Mercury {

namespace fs = std::filesystem;

namespace {

constexpr int kHistoryLength = 200;
constexpr const char* kIgnoreFile = ".loreignore";
// Written by Initialize Repository: what the editor and Bazel generate.
constexpr const char* kDefaultIgnore =
    "# Generated by the Mercury editor and Bazel; never committed\n"
    ".mercury/\n"
    "build/\n"
    "cmake-build-*/\n"
    "bazel-*/\n"
    "Builds/\n";

std::string Trim(std::string_view text) {
  const auto first = text.find_first_not_of(" \t\r\n");
  if (first == std::string_view::npos) return "";
  const auto last = text.find_last_not_of(" \t\r\n");
  return std::string(text.substr(first, last - first + 1));
}

// Lore colors its output when it thinks it's on a terminal.
std::string StripAnsi(const std::string& line) {
  std::string out;
  out.reserve(line.size());
  for (size_t i = 0; i < line.size(); i++) {
    if (line[i] == '\x1b' && i + 1 < line.size() && line[i + 1] == '[') {
      i += 2;
      while (i < line.size() && !std::isalpha(static_cast<unsigned char>(line[i]))) i++;
      continue;
    }
    out.push_back(line[i]);
  }
  return out;
}

int ParseInt(std::string_view text) {
  return std::atoi(std::string(text).c_str());
}

// "Revision  : 3" -> "3"
std::string FieldValue(const std::string& line) {
  const auto colon = line.find(':');
  return colon == std::string::npos ? "" : Trim(line.substr(colon + 1));
}

}  // namespace

LoreVcs::LoreVcs(Console& console, EditorSettings& settings)
    : console_(console), settings_(settings) {}

LoreVcs::~LoreVcs() = default;

void LoreVcs::SetProject(std::shared_ptr<Project> project) {
  queue_.clear();
  process_.reset();  // kills a running command
  output_.clear();
  project_ = std::move(project);
  refresh_queued_ = false;
  loaded_ = false;
  branch_.clear();
  local_revision_ = remote_revision_ = -1;
  sync_state_.clear();
  changes_.clear();
  history_.clear();
  locks_.clear();
  branches_.clear();
  remote_branches_.clear();
  repository_name_.clear();
  last_error_.clear();
  selected_path_.clear();
  diff_lines_.clear();
  selected_revision_ = -1;
  revision_lines_.clear();
  state_revision_++;
  // Load locks now so the Project panel can show them.
  if (project_ && IsRepository()) Refresh();
}

bool LoreVcs::IsRepository() const {
  std::error_code ec;
  return project_ && fs::is_directory(project_->GetRoot() / ".lore", ec);
}

// ---------------------------------------------------------------- Commands ---

void LoreVcs::Run(std::vector<std::string> args, Callback done, bool quiet) {
  if (!project_) return;
  queue_.push_back({std::move(args), std::move(done), quiet});
}

void LoreVcs::Update() {
  if (process_) {
    for (auto& line : process_->TakeOutput()) {
      line = StripAnsi(line);
      if (!current_.quiet && !Trim(line).empty()) {
        console_.AddProcessOutput(Console::Source::kLore, line);
      }
      output_.push_back(std::move(line));
    }
    if (!process_->IsRunning()) Finish();
  }
  if (!process_ && !queue_.empty()) StartNext();
}

void LoreVcs::StartNext() {
  while (!process_ && !queue_.empty()) {
    current_ = std::move(queue_.front());
    queue_.pop_front();

    std::vector<std::string> args = {
        settings_.lore_executable.empty() ? "lore" : settings_.lore_executable,
        "-P", "--non-interactive"};
    args.insert(args.end(), current_.args.begin(), current_.args.end());
    if (!current_.quiet) {
      std::string command = "lore";
      for (const auto& arg : current_.args) {
        command += ' ';
        command += arg.find(' ') == std::string::npos ? arg : '"' + arg + '"';
      }
      console_.Add(Console::Level::kInfo, Console::Source::kLore, "> " + command);
    }

    output_.clear();
    process_ = std::make_unique<os::Process>();
    std::string error;
    if (process_->Start(args, project_->GetRoot(), &error)) {
      state_revision_++;
      return;
    }

    // lore isn't installed (or the Options path is wrong).
    process_.reset();
    Result result;
    result.error = error + " (set the lore executable in Options)";
    if (last_error_ != result.error) {
      console_.Add(Console::Level::kError, Console::Source::kLore, result.error);
    }
    last_error_ = result.error;
    Job job = std::move(current_);
    if (job.done) job.done(result);
    state_revision_++;
  }
}

void LoreVcs::Finish() {
  for (auto& line : process_->TakeOutput()) output_.push_back(StripAnsi(line));
  Result result;
  result.exit_code = process_->GetExitCode().value_or(-1);
  result.lines = std::move(output_);
  output_.clear();
  process_.reset();

  for (const auto& line : result.lines) {
    if (line.starts_with("[Error]")) {
      result.error = Trim(line.substr(7));
      break;
    }
  }
  if (result.exit_code != 0 && result.error.empty()) {
    result.error = std::format("lore {} failed (exit code {})",
                               current_.args.empty() ? "" : current_.args[0],
                               result.exit_code);
  }
  if (!result.error.empty()) {
    // Loud commands already printed the error with their output; queries
    // that keep failing (an offline server) are reported once.
    if (current_.quiet && last_error_ != result.error) {
      console_.Add(Console::Level::kError, Console::Source::kLore,
                   "lore " + current_.args[0] + ": " + result.error);
    }
    last_error_ = result.error;
  } else if (!current_.quiet || current_.args[0] == "status") {
    // A command worked, or the server answered again.
    last_error_.clear();
  }

  Job job = std::move(current_);
  current_ = {};
  if (job.done) job.done(result);
  state_revision_++;
}

void LoreVcs::Refresh() {
  if (!IsRepository() || refresh_queued_) return;
  refresh_queued_ = true;
  Run({"status", "--scan"},
      [this](const Result& r) { if (r.ok()) ParseStatus(r.lines); }, true);
  Run({"lock", "query"},
      [this](const Result& r) { if (r.ok()) ParseLocks(r.lines); }, true);
  Run({"history", std::to_string(kHistoryLength)},
      [this](const Result& r) { if (r.ok()) ParseHistory(r.lines); }, true);
  Run({"branch", "list"},
      [this](const Result& r) { if (r.ok()) ParseBranches(r.lines); }, true);
  Run({"repository", "info"},
      [this](const Result& r) {
        if (r.ok()) ParseInfo(r.lines);
        refresh_queued_ = false;
        loaded_ = true;
      },
      true);
}

void LoreVcs::Initialize(const std::string& server_url, const std::string& repo_name) {
  if (!project_) return;
  std::string server = Trim(server_url);
  while (server.ends_with('/')) server.pop_back();
  const std::string name = Trim(repo_name);
  if (server.empty() || name.empty()) return;

  // Keep generated files out of the repository from the first commit.
  const fs::path ignore = project_->GetRoot() / kIgnoreFile;
  std::error_code ec;
  if (!fs::exists(ignore, ec)) {
    std::ofstream(ignore) << kDefaultIgnore;
  }
  Run({"repository", "create", server + "/" + name},
      [this, server](const Result& r) {
        if (!r.ok()) return;
        settings_.lore_server = server;
        settings_.Save();
        console_.Add(Console::Level::kInfo, Console::Source::kLore,
                     "Lore repository created. Stage your files and commit "
                     "to make the first revision.");
        Refresh();
      });
}

void LoreVcs::Stage(const std::vector<std::string>& paths) {
  std::vector<std::string> args = {"stage", "--"};
  args.insert(args.end(), paths.begin(), paths.end());
  Run(std::move(args), [this](const Result&) { Refresh(); });
}

void LoreVcs::StageAll() {
  Run({"stage", "--scan", "."}, [this](const Result&) { Refresh(); });
}

void LoreVcs::Unstage(const std::vector<std::string>& paths) {
  std::vector<std::string> args = {"unstage", "--"};
  args.insert(args.end(), paths.begin(), paths.end());
  Run(std::move(args), [this](const Result&) { Refresh(); });
}

void LoreVcs::Discard(const Change& change) {
  if (!project_) return;
  if (change.section == Section::kUntracked) {
    // Never committed, so there is nothing for lore to restore.
    std::error_code ec;
    fs::remove(project_->GetRoot() / change.path, ec);
    if (ec) {
      console_.Error("Could not delete " + change.path + ": " + ec.message());
    } else {
      console_.Add(Console::Level::kInfo, Console::Source::kLore,
                   "Deleted " + change.path);
    }
    if (selected_path_ == change.path) {
      selected_path_.clear();
      diff_lines_.clear();
    }
    Refresh();
    state_revision_++;
    return;
  }
  Run({"reset", "--", change.path}, [this](const Result&) { Refresh(); });
}

void LoreVcs::Commit(const std::string& raw_message, bool then_push) {
  const std::string message = Trim(raw_message);
  if (message.empty()) return;
  Run({"commit", "--", message}, [this, then_push](const Result& r) {
    if (r.ok()) {
      selected_path_.clear();
      diff_lines_.clear();
      if (then_push) {
        Push();
        return;
      }
    }
    Refresh();
  });
}

void LoreVcs::Push() {
  Run({"push"}, [this](const Result&) { Refresh(); });
}

void LoreVcs::Sync(const std::string& revision) {
  std::vector<std::string> args = {"sync"};
  if (!revision.empty()) args.push_back(revision);
  Run(std::move(args), [this](const Result&) { Refresh(); });
}

void LoreVcs::SwitchBranch(const std::string& name) {
  Run({"branch", "switch", "--", name}, [this](const Result&) { Refresh(); });
}

void LoreVcs::CreateBranch(const std::string& name) {
  Run({"branch", "create", "--", name}, [this](const Result&) { Refresh(); });
}

void LoreVcs::AmendMessage(const std::string& message) {
  Run({"revision", "amend", "--", message}, [this](const Result& r) {
    if (r.ok()) selected_revision_ = -1;
    Refresh();
  });
}

void LoreVcs::ShowDiff(const std::string& path) {
  selected_path_ = path;
  diff_lines_ = {"Loading..."};
  state_revision_++;
  Run({"diff", "--", path},
      [this, path](const Result& r) {
        if (selected_path_ != path) return;
        diff_lines_ = r.ok() ? r.lines : std::vector<std::string>{r.error};
        // Lore starts with a blank line and the path, already shown above.
        while (!diff_lines_.empty() &&
               (Trim(diff_lines_.front()).empty() || diff_lines_.front() == path)) {
          diff_lines_.erase(diff_lines_.begin());
        }
        if (diff_lines_.empty()) diff_lines_ = {"No differences"};
      },
      true);
}

void LoreVcs::ShowRevision(const Revision& revision) {
  selected_revision_ = revision.number;
  revision_lines_ = {"Loading..."};
  state_revision_++;
  const int number = revision.number;
  Run({"revision", "info", "--delta", revision.signature},
      [this, number](const Result& r) {
        if (selected_revision_ != number) return;
        revision_lines_ = r.ok() ? r.lines : std::vector<std::string>{r.error};
      },
      true);
}

void LoreVcs::LockPaths(const std::vector<std::string>& paths, bool lock) {
  std::vector<std::string> args = {"lock", lock ? "acquire" : "release", "--"};
  args.insert(args.end(), paths.begin(), paths.end());
  Run(std::move(args), [this](const Result&) { Refresh(); });
}

bool LoreVcs::IsLocked(const fs::path& path) const {
  return locks_.contains(RelativePath(path));
}

void LoreVcs::Lock(const fs::path& path) { LockPaths({RelativePath(path)}, true); }

void LoreVcs::Unlock(const fs::path& path) { LockPaths({RelativePath(path)}, false); }

std::string LoreVcs::RelativePath(const fs::path& path) const {
  if (!project_) return "";
  return path.lexically_relative(project_->GetRoot()).generic_string();
}

bool LoreVcs::IsAheadOfRemote() const {
  return sync_state_.find("ahead") != std::string::npos ||
         sync_state_.find("does not exist") != std::string::npos;
}

bool LoreVcs::HasUnpushedCommit() const {
  // Amending a pushed revision would make the branch diverge from the server.
  if (local_revision_ <= 0 || history_.empty()) return false;
  if (history_.front().number != local_revision_) return false;
  return IsAheadOfRemote();
}

std::string LoreVcs::ReadRemoteUrl() const {
  if (!project_) return "";
  std::ifstream file(project_->GetRoot() / ".lore" / "config.toml");
  std::string line;
  while (std::getline(file, line)) {
    if (!line.starts_with("remote_url")) continue;
    const auto first = line.find('"');
    const auto last = line.rfind('"');
    if (first != std::string::npos && last > first) {
      return line.substr(first + 1, last - first - 1);
    }
  }
  return "";
}

bool LoreVcs::WriteRemoteUrl(const std::string& url) {
  if (!project_) return false;
  const fs::path path = project_->GetRoot() / ".lore" / "config.toml";
  std::vector<std::string> lines;
  {
    std::ifstream file(path);
    std::string line;
    while (std::getline(file, line)) lines.push_back(line);
  }
  const std::string entry = "remote_url = \"" + url + "\"";
  auto it = std::find_if(lines.begin(), lines.end(), [](const std::string& line) {
    return line.starts_with("remote_url");
  });
  if (it != lines.end()) {
    *it = entry;
  } else {
    lines.insert(lines.begin(), entry);  // top-level keys come before tables
  }
  std::ofstream file(path, std::ios::trunc);
  for (const auto& line : lines) file << line << '\n';
  return static_cast<bool>(file);
}

// ----------------------------------------------------------------- Parsing ---

void LoreVcs::ParseStatus(const std::vector<std::string>& lines) {
  changes_.clear();
  remote_revision_ = -1;
  sync_state_.clear();
  bool in_list = false;
  Section section = Section::kUnstaged;
  for (const auto& line : lines) {
    if (line.starts_with("On branch ")) {
      // On branch <name> revision <n> -> <signature>
      const std::string rest = line.substr(10);
      const auto at = rest.find(" revision ");
      branch_ = rest.substr(0, at);
      if (at != std::string::npos) local_revision_ = ParseInt(rest.substr(at + 10));
    } else if (line.starts_with("Remote revision ")) {
      remote_revision_ = ParseInt(line.substr(16));
    } else if (line.starts_with("Local branch ") || line.starts_with("Remote branch ")) {
      sync_state_ = Trim(line);
    } else if (line == "Changes staged for commit:") {
      in_list = true;
      section = Section::kStaged;
    } else if (line == "Changes not staged for commit:") {
      in_list = true;
      section = Section::kUnstaged;
    } else if (line == "Untracked files:") {
      in_list = true;
      section = Section::kUntracked;
    } else if (line.starts_with("Tracked changes")) {
      in_list = false;
    } else if (in_list && line.size() > 2 &&
               std::isupper(static_cast<unsigned char>(line[0])) && line[1] == ' ') {
      std::string text = Trim(line.substr(2));
      // Folders come and go with the files in them.
      if (text.empty() || text.ends_with('/')) continue;
      Change change;
      change.code = line[0];
      change.section = section;
      if (const auto arrow = text.find(" -> "); arrow != std::string::npos) {
        change.from = text.substr(0, arrow);
        change.path = text.substr(arrow + 4);
      } else {
        change.path = text;
      }
      changes_.push_back(std::move(change));
    }
  }
  // A staged move is also listed as a delete of its new path; keep the move.
  std::erase_if(changes_, [this](const Change& change) {
    return change.code == 'D' &&
           std::any_of(changes_.begin(), changes_.end(), [&](const Change& other) {
             return other.code == 'V' && other.path == change.path &&
                    other.section == change.section;
           });
  });
  if (!selected_path_.empty() &&
      std::none_of(changes_.begin(), changes_.end(),
                   [this](const Change& c) { return c.path == selected_path_; })) {
    selected_path_.clear();
    diff_lines_.clear();
  }
}

void LoreVcs::ParseHistory(const std::vector<std::string>& lines) {
  history_.clear();
  for (const auto& line : lines) {
    if (line.starts_with("Revision")) {
      history_.push_back({});
      history_.back().number = ParseInt(FieldValue(line));
    } else if (history_.empty()) {
      continue;
    } else if (line.starts_with("Signature")) {
      history_.back().signature = FieldValue(line);
    } else if (line.starts_with("Date")) {
      history_.back().date = FieldValue(line);
    } else if (line.starts_with("    ")) {
      auto& message = history_.back().message;
      if (!message.empty()) message += '\n';
      message += line.substr(4);
    }
  }
}

void LoreVcs::ParseLocks(const std::vector<std::string>& lines) {
  locks_.clear();
  for (const auto& line : lines) {
    // <path> by <owner> on branch <id>
    const auto on = line.rfind(" on branch ");
    if (on == std::string::npos) continue;
    const auto by = line.rfind(" by ", on);
    if (by == std::string::npos) continue;
    locks_[line.substr(0, by)] = {line.substr(by + 4, on - by - 4),
                                  line.substr(on + 11)};
  }
}

void LoreVcs::ParseBranches(const std::vector<std::string>& lines) {
  branches_.clear();
  remote_branches_.clear();
  std::vector<std::string>* list = nullptr;
  for (const auto& line : lines) {
    if (line.starts_with("Local branches")) {
      list = &branches_;
    } else if (line.starts_with("Remote branches")) {
      list = &remote_branches_;
    } else if (list && line.size() > 2) {
      list->push_back(Trim(line.substr(2)));  // "* main" or "  main"
    }
  }
}

void LoreVcs::ParseInfo(const std::vector<std::string>& lines) {
  // "<name> (<id>)" first, then "Remote URL: ...", ...
  if (lines.empty()) return;
  const std::string& first = lines.front();
  repository_name_ = Trim(first.substr(0, first.rfind(" (")));
}

}  // namespace Mercury
